import { cp, mkdir, realpath, rm } from 'node:fs/promises';
import { join, relative, sep } from 'node:path';

import { info } from './console.mjs';
import { REPO_ROOT } from './paths.mjs';

const BUILD_PARENT_NAME = 'alent-red-build';
const BUILD_DIR_NAME = 'alent-red-desktop';

// Regenerated by the build, or private to the maintainer's machine: none of it
// belongs in the copy. node_modules and the staged core are copied: the build
// needs them.
const EXCLUDED_TOP_LEVEL = new Set([
  '.git',
  '.claude',
  'release',
  'dist',
  '.env',
  'CLAUDE.local.md',
  'MIGRATION.md',
  'mutagen.yml',
  'mutagen.yml.lock',
]);
const EXCLUDED_NESTED = new Set([join('src-tauri', 'target')]);

// A release is compiled from a copy of the repository at a fixed, machine-neutral
// location: the compiler records the crate directory into the binary, and the
// path must read the same whatever machine produced the release.
// /tmp on macOS; ProgramData on Windows, which lives outside the user profile.
export function resolveBuildRoot() {
  if (process.platform === 'win32') {
    const programData = process.env['ProgramData'] ?? 'C:\\ProgramData';
    return join(programData, BUILD_PARENT_NAME, BUILD_DIR_NAME);
  }
  return join('/tmp', BUILD_PARENT_NAME, BUILD_DIR_NAME);
}

function shouldCopy(sourcePath) {
  const relativePath = relative(REPO_ROOT, sourcePath);
  if (relativePath.length === 0) {
    return true;
  }
  const [topLevel] = relativePath.split(sep);
  if (EXCLUDED_TOP_LEVEL.has(topLevel) || topLevel.startsWith('.env.')) {
    return false;
  }
  return !EXCLUDED_NESTED.has(relativePath);
}

export async function prepareBuildRoot() {
  const buildRoot = resolveBuildRoot();
  info(`Copying the repository to ${buildRoot}`);
  await rm(buildRoot, { recursive: true, force: true });
  await mkdir(buildRoot, { recursive: true });
  await cp(REPO_ROOT, buildRoot, { recursive: true, filter: shouldCopy });
  // The compiler records the physical path (/tmp is a link to /private/tmp on
  // macOS), so the remap prefix must be the physical path too.
  return realpath(buildRoot);
}

export async function removeBuildRoot(buildRoot) {
  await rm(buildRoot, { recursive: true, force: true });
}
